type ColumnType = 'integer' | 'varchar' | 'text' | 'timestamp';

interface ColumnSpec {
  name: string;
  type: ColumnType;
  notNull?: boolean;
  note?: string;
}

type TableId = 'users' | 'posts' | 'follows';

interface TableSpec {
  id: TableId;
  name: string;
  columns: ColumnSpec[];
}

type ManyKind = 'many' | 'manyZeroOrMany';

const CHANNEL_SPACING = 26;

interface RefEnd {
  table: TableId;
  column: string;
}

interface RefSpec {
  id: string;
  label: string;
  many: RefEnd;
  one: RefEnd;
  manyKind: ManyKind;
  direction: string;
  // 同側繞行時額外外推的通道距離，讓共用同一張表的關聯線彼此分開。
  channelOffset: number;
}

type RecordRow = Record<string, string | number>;

// PK 定址鍵——單一事實來源，欄位上的 PK 徽章一律由此推導，不重複標記在 ColumnSpec 上。
